update legislacao l set aplicacao_pratica=v.a, comentario_conferencia='revisao_independente', comentario_resultado=v.r, comentario_conferido_em=date '2026-11-02' from (values
(651,'','aprovado',$q$A concessão do habeas corpus não impede nem põe fim ao processo, desde que este não esteja em conflito com os fundamentos da concessão. Na peça, demonstre se o prosseguimento do processo é compatível ou conflita com os fundamentos da ordem concedida; na defesa, convém mostrar o conflito para pedir que o processo não prossiga naquilo que contrarie esses fundamentos.$q$),
(652,'','corrigido',$q$Se o habeas corpus for concedido em virtude de nulidade do processo, este será renovado. Ao impetrar com esse fundamento, identifique com precisão a nulidade e o ato em que ela ocorreu, e junte as peças que a demonstrem. Convém advertir quem é representado de que a consequência prevista no texto é a renovação do processo. Ao analisar a ordem concedida, confira quais atos serão refeitos.$q$),
(653,'','aprovado',$q$Concedida a soltura em habeas corpus, a condenação nas custas recai sobre a autoridade que, por má-fé ou evidente abuso de poder, determinou a coação. Para pedi-la, demonstre a má-fé ou o abuso evidente de poder na petição ou nas razões e junte os atos da autoridade. O parágrafo único prevê a remessa ao Ministério Público de cópia das peças necessárias para promover a responsabilidade da autoridade; convém pedir que isso seja determinado.$q$),
(654,'','corrigido',$q$Confira quem impetra: qualquer pessoa, em favor próprio ou alheio, ou o Ministério Público. Monte a petição conforme o § 1º: nomeie a pessoa que sofre ou está ameaçada de coação e quem exerce a violência, coação ou ameaça (a); declare a espécie de constrangimento ou, se for simples ameaça, as razões do temor (b); e inclua a assinatura do impetrante, ou de alguém a seu rogo quando não souber ou não puder escrever, e a designação das residências (c). Antes de protocolar, revise cada item e anexe os documentos que sustentem as razões. O § 2º dá a juízes e tribunais competência para expedir a ordem de ofício quando, no curso de processo, verificarem coação ilegal em curso ou iminente; nesse caso, a peça pode apontar os elementos do processo que mostram a coação.$q$),
(655,'','corrigido',$q$Se houver embaraço ou demora na expedição de ordem de habeas corpus, nas informações sobre a causa da prisão, na condução e apresentação do paciente ou na soltura, descreva o fato na peça, identifique o agente (carcereiro, diretor da prisão, escrivão, oficial de justiça ou autoridade judiciária ou policial) e junte o que o comprove. A multa é de duzentos mil-réis a um conto de réis, sem prejuízo das penas em que o agente incorrer. Quem a impõe depende do agente: o juiz do tribunal que julgar o habeas corpus ou, se se tratar de autoridade judiciária, o Supremo Tribunal Federal ou o Tribunal de Apelação.$q$),
(656,'','aprovado',$q$Recebida a petição, o juiz pode, se julgar necessário e estando preso o paciente, mandar que lhe seja apresentado em dia e hora que designar. Na petição, convém pedir a apresentação do paciente, explicando por que é necessária, e indicar onde ele se encontra. No caso de desobediência, o parágrafo único prevê mandado de prisão contra o detentor e que o juiz providencie para que o paciente seja tirado da prisão e apresentado em juízo; se a ordem de apresentação não for cumprida, junte a prova do descumprimento.$q$),
(657,'','aprovado',$q$Na defesa, se a apresentação do paciente preso não ocorreu, confira se a justificativa se enquadra em um dos incisos: grave enfermidade do paciente (I); não estar ele sob a guarda da pessoa a quem se atribui a detenção (II); ou comparecimento que não tenha sido determinado pelo juiz ou pelo tribunal (III). Convém juntar atestado para a hipótese do inciso I e demonstrar quem tem a guarda na do inciso II. O juiz pode ir ao local em que o paciente se encontrar, se este não puder ser apresentado por motivo de doença (parágrafo único).$q$),
(658,'','aprovado',$q$O detentor declara à ordem de quem o paciente está preso. Ao conferir as informações do habeas corpus, verifique se o detentor declarou a ordem a que o paciente está submetido e, se não declarou, indique isso na petição, pedindo que o juiz o determine. O artigo não prevê consequência para a omissão.$q$)
) as v(n,t,r,a) where l.codigo='cpp' and l.numero=v.n and coalesce(l.titulo,'')=v.t and l.paragrafo is null and l.inciso is null and l.vigente;

